<video src="media/v2v-source.mp4" poster="media/v2v-source.jpg" controls="" playsinline="" preload="metadata" aria-label="Vid\xE9o source tourn\xE9e pour le V2V" style="display: block; width: 100%; aspect-ratio: 16 / 9; background: #3A0207; object-fit: contain"></video>
